-- 2026-11-11 知识点精修：node 40（A1-1.1.1）
-- 将第 7 项后的“如下图所示：”与图片紧邻，后续编号项放在图片下方。
-- 旧 revision 保留可回滚。
begin;
create temp table _kb_img_fix(node_id integer primary key, blocks jsonb not null) on commit drop;
insert into _kb_img_fix values (40, $kb$[{"t":"list","id":"a1-1-1-1-b1","imp":"core","items":["1、1946 年美国宾州大学研制成功第1 台数字电子计算机-==ENIAC==。","2、==冯∙诺依曼==提出“==存储程序控制==”原理：程序和数据必须从外存调入内存，再交给CPU。"],"title":"","ordered":false},{"h":549,"t":"img","w":1191,"id":"a1-1-1-1-b2","imp":"normal","src":"/kb-assets/theory/p6_r0_6c5dade9e65d45c2.png","title":""},{"t":"list","id":"a1-1-1-1-b3","imp":"core","items":["3、计算机发展的四个阶段：","第^^一^^代^^电子管计算机^^时代（1946-1958）：真空电子管，使用==机器语言或汇编语言。==","第==二==代==晶体管计算机==时代（1959-1964）：晶体管，出现==高级程序设计语言。==","第^^三^^代^^中小规模集成电路计算机^^时代（1965-1970）：中小规模集成电路，^^操作系统和数据库系统出现。^^","第^^四^^代^^大规模集成电路计算机^^时代（1971-至今）：大规模和超大规模集成电路，网络技术，多媒体技术等出现。","4、计算机的分类：","（1）按照计算机的工作原理：数字式电子计算机、模拟式电子计算机、数字模拟混合式电子计算机。","（2）按照计算机的用途：通用计算机、专用计算机。","（3）^^按照计算机的性能（规模）划分：巨型机（“神威”、“天河”系列等）、小巨型机、大型机、小型机、工作站、个人计算机（PC）、嵌入式计算机（核心是SoC 片上系统）。^^","（4）按主机外型：台式、便携式。","（5）按中央处理器的字长分：8 位、16 位、32 位、64 位等。","5、计算机的特点：^^运算速度快、运算精度高、存储容量大、可靠性高、能进行逻辑判断、支持人机交互等。^^","6、计算机的应用领域：科学计算、信息处理、计算机辅助技术（辅助设计CAD;辅助制造CAM、辅助教学CAI、辅助测试CAT、办公自动化OA）、过程控制、人工智能、网络应用、多媒体等。","7、==计算机系统==是由==硬件系统==和==软件系统==组成。","==硬件==主要由==五大部件==构成：==运算器==、==控制器==、==存储器==、==输入设备==和==输出设备==，它们通过总线相互连接。","如下图所示："],"title":"","ordered":false},{"h":472,"t":"img","w":834,"id":"a1-1-1-1-b4","imp":"normal","src":"/kb-assets/theory/p7_r0_aff251d8271afc55.png","title":""},{"t":"list","id":"a1-1-1-1-b3b","imp":"core","items":["8、==按性能与用途划分的各类计算机==：巨型计算机（超级计算机）采用并行处理，用于==军事科研、气象预报、石油勘探、生物信息处理、飞机设计等领域==，我国目前最快的是“神威·太湖之光”。大型计算机为企业、政府的海量数据提供集中的存储、管理和处理，承担主服务器（企业级服务器）的功能，可一二十年不间断运行。服务器是网络中专门为其他计算机提供资源和服务的计算机，需 7×24 小时运行，分为工作组级（家用）、部门级、企业级服务器，浪潮集团是我国最大的服务器制造商；服务器有三种应用方式：作为服务器、作为个人计算机、嵌入式应用。","9、==计算机硬件组成：主机与外设==：硬件是计算机系统中所有实际物理装置的总称，如 CPU 芯片、存储器芯片、鼠标、键盘、硬盘；硬件是软件的载体，软硬件缺一不可。CPU 和主存储器构成==主机的主体部分==，I/O 设备和辅助存储器构成外围设备（外设）。主存储器（内存、主存）存取速度快、容量小、成本高，断电后信息几乎消失（BIOS 中的只读 ROM 除外），属易失性存储器；它存放已经启动的应用程序和需立即处理的数据，CPU 处理的指令和数据直接从内存取得；主存与 CPU 高速连接，按字节编址（每个字节都有地址），是计算机的工作存储器。","10、==计算机的诞生与发展==：计算机速度不断提高、功能增加、体积缩小、成本降低、应用扩大，发展之快不断改写预测：早期 8～10 年运算速度提高十倍，而成本和体积降为原来的 1/10；20 世纪 80 年代开始，几乎每三年性能提高近四倍，成本下降一半。推动力是微电子技术的进展和计算机应用的需求。","11、==操作系统的四大功能==：^^操作系统的功能主要有四个^^：==处理器管理（宏观上同时执行、微观上单一执行==，采用时间片轮转的处理策略）；存储管理（采用“虚拟存储技术”，虚拟存储器由物理内存和硬盘上的页面文件组成，使用 LRU 算法）；文件管理（多级层次式树状结构）；设备管理（通过“我的电脑”快捷菜单“属性”中的“设备管理器”进行）。","12、==多任务处理的机制与前后台任务==：多任务处理指多个任务在计算机中同时运行，每个任务都可以使用包括 ==CPU 在内的几乎全部软硬件资源==。任务是指装入内存并启动执行的一个程序。为支持多任务处理，操作系统中的处理器调度程序负责把 CPU 时间分配给各个任务，使多个任务“同时”执行。调度程序采用按时间片轮转的方法，每个任务轮流得到一个时间片的 CPU 时间，时间片结束后再把 CPU 交给下一个任务，因此一个 CPU 就可以“同时”执行多个任务。","13、==实用程序包括哪些==：实用程序包括磁盘扫描程序、磁盘清理程序、磁盘碎片整理程序、备份程序、杀毒软件、基本输入输出系统（BIOS）、防火墙等。"],"title":"","ordered":false},{"t":"callout","id":"a1-1-1-1-b5","imp":"core","kind":"tip","text":"专转本常考主线：==计算机四代划分以元器件为标志==（电子管→晶体管→中小规模IC→大规模/超大规模IC）；==冯·诺依曼“存储程序控制”==核心思想在于程序与数据预先存入内存储器，由 CPU 自动连续取指并执行；计算机按性能划分为==巨型机（超级计算机，我国神威系列）、大型机、小型机、微型机（PC）、嵌入式系统==。","title":"考向复习提示：计算机分类与存储程序原理"},{"t":"callout","id":"a1-1-1-1-b6","imp":"core","kind":"trap","text":"专转本常考单选：冯·诺依曼型计算机由五大基本逻辑部件组成：==运算器、控制器、存储器、输入设备、输出设备==；指令和数据均以二进制形式存放在同一个存储器中，由 CPU 顺序执行；常考陷阱选项故意将“存储器”偷换为“外存储器”或漏掉“控制器”，务必精准辨析。","title":"高频易错陷阱：冯·诺依曼架构五大逻辑部件"}]$kb$::jsonb);
do $$
declare old_rev record; v_rev integer; n integer;
begin
  select rev_no, html, search_text, source_ref into old_rev
    from kb_revision where node_id=40 and rev_no=(select published_rev from kb_entry where node_id=40);
  if not found then raise exception 'node 40 找不到已发布 revision'; end if;
  select coalesce(max(rev_no),0)+1 into v_rev from kb_revision where node_id=40;
  insert into kb_revision(node_id, rev_no, blocks, html, search_text, source_ref)
  select 40, v_rev, t.blocks, old_rev.html, old_rev.search_text, old_rev.source_ref from _kb_img_fix t;
  update kb_entry set published_rev=v_rev, updated_at=now() where node_id=40;
  select jsonb_array_length(blocks) into n from _kb_img_fix where node_id=40;
  if n <> 7 then raise exception 'node 40 block 数量异常: %', n; end if;
end $$;
commit;
